                        RUN_JOB_PARAMS, effectiveConfig),
                    tokens: spTokens,
                    runs: spRunList,
                    checkNames: validationCheckNames() || [],
                    prev: spPrev,
                    dryRun: DRY,
                    processed: processedKeys
