                // one extra gh call, the accumulation source for label
                // timestamps (reviewedAt/approvedAt/validatingAt/
                // devStartedAt). All three degrade to empty/null on any
                // miss: a partial snapshot beats a dead tick.
                var spMerged = [];
                try {
