                    // history is a board affordance — never fail the tick
                    console.warn('  ⚠️  factory state history failed: ' +
                                 (eHist.message || eHist));
                }
            }
        } catch (ePub) {
            console.warn('  ⚠️  factory state publish failed: ' +
                         (ePub.message || ePub));
        }
    }

    return { processedKeys: processedKeys, skippedKeys: skippedKeys };
