                                              // assignment bucketing (null)
var HISTORY_CAP = 24;                         // bound snapshot growth
var DEFAULT_TOKENS_FILE = 'outputs/token_usage/factory_tokens.json';
var BACKLOG_CAP = 50;                         // per bucket — github_search_issues
