    /** One tick with statePublish on; returns {sm, state} — state parsed
     *  from the fa-state.json PUT payload. */
    function publishTick(opts) {
        opts = opts || {};
        var sm = makeSmAgent(opts);
        sm.action({ jobParams: {
            owner: 'o', repo: 'r', rules: [], statePublish: SP
